    renderList();
    updateCounts();
    if (current.length) select(current[0].row_id);
  }).catch((error) => {
    byId("source").textContent = "Worksheet unavailable";
    byId("load-error").textContent = error.message;
    byId("load-error").hidden = false;
  });
})();

